"""Pair function generated by symox, per dialect (contract v0).

``pair_function(plan, dialect)`` produces a scalar device function,
independent of the kernel strategy::

    // cuda/hip: __device__ __forceinline__; sycl: inline
    struct kp_out { T o0; ...; };                    // bool for COUNT
    kp_out kp_pair(const T* __restrict__ xi_0, ...,   // one pointer per i arg
                   const T* __restrict__ yj_0, ...,   // one pointer per j arg
                   const T* __restrict__ p_0, ...);   // one pointer per param

Pointers follow the order of ``plan.args``; their names are ``xi_<n>``,
``yj_<n>``, ``p_<n>``, where ``<n>`` is the rank of the argument among those
with the same role. ``PairSource.arg_layout`` gives the exact mapping.

Numerical policy (see ``docs/numerics.md``):

- never fast-math (``plan.fast_math=True`` → ``UnsupportedError``);
- ``1/sqrt(x)`` is NOT replaced by ``rsqrt`` (reduced precision in CUDA);
- no FP64 → FP32 conversion: all temporaries have type ``T``;
- region-aware CSE in the presence of ``Piecewise`` (``where``), see
  `_region_cse`: a common subexpression is hoisted (evaluated
  unconditionally) only if it is already evaluated outside any branch
  (condition of the outermost ``where``, unconditional part) or if it
  appears in at least two distinct regions; otherwise it stays in its
  branch. This is safe because the generated code has no side effects and
  the targeted GPUs have no floating-point traps: a value computed outside
  its domain (``sqrt(-1)``, ``1/0``, ``log(0)``) yields NaN/inf without
  aborting the kernel, and it is only read by the branches that consume it;
  the C ternary keeps the value of the active branch, the same as a
  non-hoisted evaluation (up to the FMA contraction choice, already allowed
  by ``fp_contract``). User functions (unknown cost or side effects) are
  never hoisted.

Source dependencies: none for CUDA/NVRTC; HIP: ``hip/hip_runtime.h``
(included automatically by hipcc/hiprtc); SYCL: ``<sycl/sycl.hpp>`` must
be included by the backend before the source (``sycl::`` functions).

"To propose to symox": symox already exposes ``cuda_device_function``
(``__device__`` function with scalar arguments) and ``syclcode_function``
(``inline`` function with scalar arguments). What is missing, in a general and
reusable form: (1) an explicit HIP dialect, (2) vector arguments passed by
``const T* __restrict__`` pointer, loading only the components used,
(3) an output struct named by the caller and typed bool/T, (4) the
``use_rsqrt=False`` control exposed in device functions, (5) a rounding
policy for ``Float`` constants to the dtype. This module implements these
points on the Kernox side, reusing the symox printers and helpers.
"""

from __future__ import annotations

import dataclasses
import hashlib
import re
from dataclasses import dataclass

from .. import _symox_compat
from ..builder import is_boolean
from ..errors import UnsupportedError, ValidationError
from ..plan import Plan

GENERATOR_VERSION = "kernox-pair-v2"
DIALECTS = ("cuda", "hip", "sycl")
_PREFIX = {"i": "xi", "j": "yj", "param": "p"}
_CTYPE = {"float32": "float", "float64": "double"}


@dataclass(frozen=True)
class ArgLayout:
    """C parameter ``param`` ↔ plan argument ``arg`` (role, dim)."""

    param: str
    arg: str
    role: str
    dim: int


@dataclass(frozen=True)
class PairSource:
    """Generated source; the ``source``, ``name``, ``out_type`` and ``arg_layout``
    fields are fixed by contract v0, the others are backward-compatible additions."""

    source: str
    name: str
    out_type: str
    arg_layout: tuple[ArgLayout, ...]
    dialect: str = "cuda"
    scalar_type: str = "float"                 # T
    out_fields: tuple[str, ...] = ()           # "o0", "o1"...
    out_ctypes: tuple[str, ...] = ()           # "float" | "double" | "bool"
    generator_version: str = GENERATOR_VERSION

    @property
    def sha256(self) -> str:
        return hashlib.sha256(self.source.encode()).hexdigest()


_POW_HELPERS = {f"kp_pow{n}": f"kp_pow{n}" for n in (2, 3, 4)}

# --------------------------------------------------------------------- FP16 (amendment v0.9)
# FP16 type of the hip dialect: ``kp_h`` wraps ``_Float16`` so that every operation
# is rounded to binary16 (semantics of the Torch oracle). With a bare ``_Float16``, a
# ``1.5F`` literal or an ``expf`` call would promote the computation to FP32. Conversions
# to kp_h are implicit (constants, integers; round to nearest), conversions from kp_h
# are explicit: no built-in float operator is a candidate. Math functions: computed
# in float, then rounded to FP16 (like Torch on CPU).
# "To propose to symox": a float16 dtype for ``cudacode``/``cudacode_function``.
HALF_UNARY = ("expf", "logf", "sqrtf", "fabsf", "sinf", "cosf", "tanf", "asinf", "acosf", "atanf",
              "sinhf", "coshf", "tanhf", "floorf", "ceilf", "expm1f", "log1pf", "exp2f", "log2f",
              "log10f", "erff", "erfcf", "cbrtf", "roundf", "truncf", "rintf")
HALF_BINARY = ("powf", "atan2f", "fminf", "fmaxf", "copysignf", "fmodf", "hypotf")
HALF_PRELUDE = ("""#ifndef KP_HALF_DEFINED
#define KP_HALF_DEFINED
struct kp_h {
  _Float16 v;
  kp_h() = default;
  __device__ __forceinline__ kp_h(float x) : v((_Float16)x) {}
  __device__ __forceinline__ kp_h(double x) : v((_Float16)x) {}
  __device__ __forceinline__ kp_h(int x) : v((_Float16)x) {}
  __device__ __forceinline__ kp_h(long long x) : v((_Float16)x) {}
  __device__ __forceinline__ explicit operator float() const { return (float)v; }
  __device__ __forceinline__ explicit operator double() const { return (double)v; }
};
__device__ __forceinline__ kp_h kp_hraw(_Float16 x) { kp_h r; r.v = x; return r; }
#define KP_HBIN(op) __device__ __forceinline__ kp_h operator op(kp_h a, kp_h b) { return kp_hraw(a.v op b.v); }
KP_HBIN(+) KP_HBIN(-) KP_HBIN(*) KP_HBIN(/)
#undef KP_HBIN
#define KP_HCMP(op) __device__ __forceinline__ bool operator op(kp_h a, kp_h b) { return a.v op b.v; }
KP_HCMP(<) KP_HCMP(>) KP_HCMP(<=) KP_HCMP(>=) KP_HCMP(==) KP_HCMP(!=)
#undef KP_HCMP
#define KP_HSET(op) __device__ __forceinline__ kp_h& operator op##=(kp_h& a, kp_h b) { a.v = a.v op b.v; return a; }
KP_HSET(+) KP_HSET(-) KP_HSET(*) KP_HSET(/)
#undef KP_HSET
__device__ __forceinline__ kp_h operator-(kp_h a) { return kp_hraw(-a.v); }
__device__ __forceinline__ kp_h operator+(kp_h a) { return a; }
"""
    + "".join(f"__device__ __forceinline__ kp_h {f}(kp_h x) {{ return kp_h({f}((float)x)); }}\n" for f in HALF_UNARY)
    + "".join(f"__device__ __forceinline__ kp_h {f}(kp_h x, kp_h y) {{ return kp_h({f}((float)x, (float)y)); }}\n"
              for f in HALF_BINARY)
    + "#endif\n")
_HALF_CALLS_OK = set(HALF_UNARY + HALF_BINARY) | {"kp_pow2", "kp_pow3", "kp_pow4", "kp_h", "__int_as_float",
                                                  "if", "return", "sizeof", "defined"}


def _half_source(ps: "PairSource", plan: Plan) -> "PairSource":
    """FP32 → FP16 source (``kp_h``); explicit refusal if a function has no overload."""
    lines = ps.source.split("\n")
    lines[0] = re.sub(r"plan \S+", f"plan {plan.key()}", lines[0]) + " [float16: kp_h]"
    body = re.sub(r"\bfloat\b", "kp_h", "\n".join(lines))
    code = re.sub(r"(?m)//[^\n]*|^\s*#[^\n]*", "", body)   # comments, preprocessor
    for fn in set(re.findall(r"\b([A-Za-z_]\w*)\s*\(", code)):
        if fn not in _HALF_CALLS_OK and fn not in (ps.name, "kp_out", ps.out_type) and not fn.startswith("_kp"):
            raise UnsupportedError(f"dtype float16: function {fn} has no FP16 overload (hip backend)")
    return dataclasses.replace(
        ps, source=HALF_PRELUDE + body, scalar_type="kp_h",
        out_ctypes=tuple("kp_h" if c == "float" else c for c in ps.out_ctypes))


def _emit_factory(dialect: str, dtype: str):
    if dialect in ("cuda", "hip"):
        from symox.extra import cudacode

        ctype = _CTYPE[dtype]

        def base(expr):
            # math_macros=False: constants (pi, e...) as literals, M_PI is missing under NVRTC
            return cudacode(expr, dtype=ctype, fast_math=False, use_rsqrt=False,
                            math_macros=False, user_functions=_POW_HELPERS)

        # recent symox: native logical operators; pinned commit: workaround
        return base if _symox_compat.cuda_logic() else _with_boolean_operators(base)
    from symox import _core

    def emit(expr):
        return _core._syclcode(expr, dtype=dtype, user_functions=_POW_HELPERS)

    return emit


_LOGIC = {"And": "&&", "Or": "||", "Xor": "!="}


def _with_boolean_operators(base):
    """Extends a printer lacking ``And/Or/Xor/Not`` (symox ``cudacode`` at 2e623e6).

    Each maximal logical subtree is replaced by a placeholder symbol, the
    rest is printed by ``base``, then the placeholders are replaced by
    ``(a) && (b)``, ``(a) || (b)``, ``(a) != (b)`` (boolean xor), ``!(a)``.
    The operands are pure booleans: the lack of short-circuiting has no
    observable effect. "To propose to symox": support for logical
    operators in ``cudacode``.
    """
    import re

    import symox

    def emit(expr):
        name = type(expr).__name__
        if name in _LOGIC:
            parts = [f"({emit(a)})" for a in expr.args]
            text = parts[0]
            for part in parts[1:]:
                text = f"({text} {_LOGIC[name]} {part})"
            return text
        if name == "Not":
            return f"(!({emit(expr.args[0])}))"
        mapping = {}

        def collect(node):
            if type(node).__name__ in _LOGIC or type(node).__name__ == "Not":
                mapping.setdefault(node, symox.Symbol(f"_kp_ph{len(mapping)}_"))
                return
            for arg in node.args:
                collect(arg)

        collect(expr)
        if not mapping:
            return base(expr)
        text = base(expr.xreplace(mapping))
        for node, ph in mapping.items():
            code = "(" + emit(node) + ")"
            text = re.sub(rf"\b{ph.name}\b", lambda _m, c=code: c, text)
        return text

    return emit


def _rewrite_integer_powers(expr):
    """``b**n`` (integer n, 2 <= |n| <= 4) → ``kp_pow{|n|}(b)`` (explicit products).

    Avoids the ``powf(a - b, 2)`` emitted by the CUDA printer for a compound base.
    The ``v*v`` products are correctly rounded; ``1/kp_pow{n}`` for n < 0.
    "To propose to symox": inlining of small integer powers for any base
    in ``cudacode``.
    """
    import symox

    helpers = {n: symox.Function(f"kp_pow{n}") for n in (2, 3, 4)}

    def query(e):
        return e.is_Pow and e.exp.is_Integer and 2 <= abs(int(e.exp)) <= 4

    def value(e):
        n = int(e.exp)
        r = helpers[abs(n)](e.base)
        return 1 / r if n < 0 else r

    return expr.replace(query, value)


_HELPERS_TEMPLATE = """#ifndef KP_PAIR_HELPERS
#define KP_PAIR_HELPERS
{q} float kp_pow2(float v) {{ return v * v; }}
{q} float kp_pow3(float v) {{ return v * v * v; }}
{q} float kp_pow4(float v) {{ const float t = v * v; return t * t; }}
{q} double kp_pow2(double v) {{ return v * v; }}
{q} double kp_pow3(double v) {{ return v * v * v; }}
{q} double kp_pow4(double v) {{ const double t = v * v; return t * t; }}
#endif
"""

# binary16 overloads (sycl::half op sycl::half stays in half: each product
# is rounded to FP16, like the oracle).
_HALF_HELPERS = """#ifndef KP_PAIR_HELPERS_HALF
#define KP_PAIR_HELPERS_HALF
inline sycl::half kp_pow2(sycl::half v) { return v * v; }
inline sycl::half kp_pow3(sycl::half v) { return v * v * v; }
inline sycl::half kp_pow4(sycl::half v) { const sycl::half t = v * v; return t * t; }
#endif
"""

_CUDA_PREAMBLE = """#ifndef INFINITY
#define INFINITY (__int_as_float(0x7f800000))
#endif
#ifndef NAN
#define NAN (__int_as_float(0x7fffffff))
#endif
"""


def _expand_ite(expr):
    """Replaces ``ITE(c, a, b)`` (boolean) with ``(c & a) | (~c & b)``.

    symox creates ``ITE`` nodes when simplifying a ``where`` inside a condition
    (``where(where(c, u, v) > 0, ...)``); neither ``cudacode`` nor ``_syclcode``
    prints them. ``a`` and ``b`` are pure booleans (comparisons, logic):
    evaluating both has no observable effect, since a comparison with NaN is
    simply false. "To propose to symox": print ``ITE`` as a ternary.
    """
    from symox.logic.boolalg import ITE

    import symox

    for _ in range(64):
        found = [a for a in expr.atoms(ITE)]
        if not found:
            return expr
        expr = expr.xreplace({
            a: symox.Or(symox.And(a.args[0], a.args[1]), symox.And(symox.Not(a.args[0]), a.args[2]))
            for a in found
        })
    raise UnsupportedError("ITE nested too deeply")


def _regions(exprs, temps):
    """Set of regions where each symbol of ``temps`` appears.

    The root region ``()`` is evaluated unconditionally (outside ``Piecewise``,
    first condition of an unconditional ``Piecewise``). Branch ``k`` of a
    ``Piecewise`` and its subsequent conditions are child regions.
    """
    import symox

    found = {t: set() for t in temps}
    counter = [0]

    def walk(e, region):
        if e in found:
            found[e].add(region)
            return
        if isinstance(e, symox.Piecewise):
            counter[0] += 1
            pid = counter[0]
            for k, (value, cond) in enumerate(e.args):
                walk(cond, region if k == 0 else region + ((pid, "c", k),))
                walk(value, region + ((pid, k),))
            return
        for a in e.args:
            walk(a, region)

    for e in exprs:
        walk(e, ())
    return found


def _region_cse(exprs, prefix="_kp_t"):
    """CSE that is valid in the presence of ``where`` (see the module policy).

    Starts from the full symox CSE, then each temporary, from last to first,
    is kept (hoisted, evaluated unconditionally) if it appears in the root
    region (including in the value of an already hoisted temporary) or in at
    least two distinct regions; otherwise it is substituted back into its
    single branch. Calls to undefined functions other than the ``kp_pow*``
    helpers (user functions, unknown cost or side effects) are never
    hoisted.
    """
    import symox
    from symox.extra.codegen.pytorch import _cse_preserving_assumptions

    replacements, exprs = _cse_preserving_assumptions(exprs, prefix)
    kept = []  # (symbol, value), reverse order
    for symbol, value in reversed(replacements):
        values = [v for _, v in kept]
        regions = _regions(list(exprs) + values, {symbol})[symbol]
        in_kept = any(symbol in v.free_symbols for v in values)
        opaque = any(isinstance(f, symox.core.function.AppliedUndef) and not str(f.func).startswith("kp_pow")
                     for f in value.atoms(symox.Function))
        if not opaque and (in_kept or () in regions or len(regions) >= 2):
            kept.append((symbol, value))
        else:
            sub = {symbol: value}
            exprs = [e.xreplace(sub) for e in exprs]
            kept = [(s_, v.xreplace(sub)) for s_, v in kept]
    return list(reversed(kept)), exprs


def pair_function(
    plan: Plan,
    dialect: str,
    *,
    name: str = "kp_pair",
    out_type: str = "kp_out",
    cse: bool = True,
) -> PairSource:
    """Generates the pair function of ``plan`` in ``dialect`` (cuda|hip|sycl).

    ``name``/``out_type`` can be changed to include several plans in a
    single compilation unit.
    """
    import symox
    from symox.extra.codegen.pytorch import _contains_conditionals, _cse_preserving_assumptions

    if dialect not in DIALECTS:
        raise ValidationError(f"unknown dialect {dialect!r} (expected one of {DIALECTS})")
    for ident in (name, out_type):
        if not (isinstance(ident, str) and ident.isidentifier() and ident.isascii()) or ident.startswith("_kp"):
            raise ValidationError(f"invalid C identifier: {ident!r}")
    if plan.fast_math:
        raise UnsupportedError("fast_math is not supported by any Kernox generator")
    if plan.dtype == "float16":
        # amendment v0.9: hip emulates half (FP32 pair rewritten to kp_h, binary16
        # rounding per operation); sycl uses native sycl::half (requires the symox
        # half printer). cuda rewrites its own FP32 pair (backend).
        if dialect == "hip":
            p32 = dataclasses.replace(plan, dtype="float32", acc_dtype="float32", sum_scheme="direct")
            return _half_source(pair_function(p32, dialect, name=name, out_type=out_type, cse=cse), plan)
        if dialect != "sycl":
            raise UnsupportedError(f"dtype float16: pair function not available in the {dialect} dialect")
        if not _symox_compat.sycl_half():
            raise UnsupportedError("dtype float16: the symox SYCL printer does not support sycl::half "
                                   "(requires symox with SyclDtype::Float16)")
        T = "sycl::half"
    elif plan.dtype not in _CTYPE:
        raise ValidationError(f"invalid dtype {plan.dtype!r}")
    else:
        T = _CTYPE[plan.dtype]

    # C names of the parameters and components (symbols safely renamed).
    layout, counters, rename, loads = [], {"i": 0, "j": 0, "param": 0}, {}, {}
    for a in plan.args:
        param = f"{_PREFIX[a.role]}_{counters[a.role]}"
        counters[a.role] += 1
        layout.append(ArgLayout(param, a.name, a.role, a.dim))
        for c, s in enumerate(a.symbols):
            local = symox.Symbol(f"_kp_{param}_{c}", **s.assumptions0)
            rename[s] = local
            loads[local] = f"{param}[{c}]"

    qualifier = "__device__ __forceinline__" if dialect in ("cuda", "hip") else "inline"
    fields = tuple(f"o{n}" for n in range(len(plan.outputs)))
    header = f"// Generated by kernox.codegen.pair ({GENERATOR_VERSION}), dialect {dialect}, plan {plan.key()}"
    out_ctypes = tuple("bool" if is_boolean(e) else T for e in plan.outputs)
    conditional = _contains_conditionals(list(plan.outputs))
    # symox cudacode_function applies no CSE in the presence of Piecewise:
    # the local path handles region-aware CSE.
    if dialect in ("cuda", "hip") and _symox_compat.cudacode_function() and not (cse and conditional):
        source = _via_symox_device_function(plan, dialect, name, out_type, fields, layout, cse, header, qualifier)
        return PairSource(source=source, name=name, out_type=out_type, arg_layout=tuple(layout),
                          dialect=dialect, scalar_type=T, out_fields=fields, out_ctypes=out_ctypes)

    exprs = [e.xreplace(rename) for e in plan.outputs]
    exprs = [_rewrite_integer_powers(_expand_ite(e)) for e in exprs]
    replacements = []
    if cse and exprs:
        if conditional:
            replacements, exprs = _region_cse(exprs, "_kp_t")
        else:
            replacements, exprs = _cse_preserving_assumptions(exprs, "_kp_t")

    emit = _emit_factory(dialect, plan.dtype)
    used = set()
    for _, value in replacements:
        used |= value.free_symbols
    for e in exprs:
        used |= e.free_symbols

    lines = [header]
    if dialect in ("cuda", "hip"):
        lines.append(_CUDA_PREAMBLE.rstrip())
    lines.append(_HELPERS_TEMPLATE.format(q=qualifier).rstrip())
    if T == "sycl::half":
        lines.append(_HALF_HELPERS.rstrip())
    lines.append(f"struct {out_type} {{")
    lines += [f"    {ct} {f};" for ct, f in zip(out_ctypes, fields)]
    lines.append("};")
    params = ", ".join(f"const {T}* __restrict__ {l.param}" for l in layout)
    lines.append(f"{qualifier} {out_type} {name}({params}) {{")
    for l in layout:
        if not any(rename[s] in used for s in next(a for a in plan.args if a.name == l.arg).symbols):
            lines.append(f"    (void){l.param};")
    for local, load in loads.items():
        if local in used:
            lines.append(f"    const {T} {local.name} = {load};")
    for symbol, value in replacements:
        ctype = "bool" if is_boolean(value) else T
        lines.append(f"    const {ctype} {symbol.name} = {emit(value)};")
    lines.append(f"    {out_type} _kp_r;")
    for f, ct, e in zip(fields, out_ctypes, exprs):
        lines.append(f"    _kp_r.{f} = ({ct})({emit(e)});")
    lines.append("    return _kp_r;")
    lines.append("}")
    return PairSource(
        source="\n".join(lines) + "\n",
        name=name,
        out_type=out_type,
        arg_layout=tuple(layout),
        dialect=dialect,
        scalar_type=T,
        out_fields=fields,
        out_ctypes=out_ctypes,
    )


def _via_symox_device_function(plan, dialect, name, out_type, fields, layout, cse, header, qualifier):
    """Recent symox path: ``symox.extra.cudacode_function`` (pointers, named struct).

    Same ABI as the pinned-commit path: ``xi_<n>``... parameters,
    ``struct out_type`` always present (outputs passed as a list), ``o<n>``
    fields, ``kp_pow*`` helpers (no base is repeated textually), no CSE in
    the presence of ``Piecewise``, no rsqrt and no fast-math.
    """
    from symox.extra import cudacode_function

    exprs = [_rewrite_integer_powers(_expand_ite(e)) for e in plan.outputs]
    body = cudacode_function(
        name,
        [list(a.symbols) for a in plan.args],
        exprs,
        dtype=plan.dtype,
        dialect=dialect,
        cse=cse,
        arg_names=[l.param for l in layout],
        result_type=out_type,
        result_fields=list(fields),
        use_rsqrt=False,
        reciprocal_sqrt=False,
        user_functions=_POW_HELPERS,
    )
    return "\n".join([header + " (symox cudacode_function)", _HELPERS_TEMPLATE.format(q=qualifier).rstrip(), body.rstrip()]) + "\n"


__all__ = ["ArgLayout", "PairSource", "pair_function", "DIALECTS", "GENERATOR_VERSION", "HALF_PRELUDE"]
